import{_ as e,o as d,c as r,a4 as a}from"./chunks/framework.BRzJ4ijD.js";const p=JSON.parse('{"title":"附录: 密码学考试 / 工程 checklist","description":"","frontmatter":{},"headers":[],"relativePath":"crypto/appendix.md","filePath":"crypto/appendix.md","lastUpdated":1788475713000}'),i={name:"crypto/appendix.md"};function s(o,t,n,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="附录-密码学考试-工程-checklist" tabindex="-1">附录: 密码学考试 / 工程 checklist <a class="header-anchor" href="#附录-密码学考试-工程-checklist" aria-label="Permalink to &quot;附录: 密码学考试 / 工程 checklist&quot;">​</a></h1><h2 id="a-1-—-algorithm-cheat-sheet" tabindex="-1">A.1 — Algorithm cheat sheet <a class="header-anchor" href="#a-1-—-algorithm-cheat-sheet" aria-label="Permalink to &quot;A.1 — Algorithm cheat sheet&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Class</th><th>Algorithm</th><th>Key Size</th><th>Use</th><th>Notes</th></tr></thead><tbody><tr><td>Symmetric block</td><td>AES-128 / AES-256</td><td>16/32 B</td><td>bulk encryption</td><td>use AES-NI hardware if available</td></tr><tr><td>Symmetric stream</td><td>ChaCha20</td><td>32 B</td><td>bulk encryption</td><td>when no AES acceleration</td></tr><tr><td>MAC</td><td>HMAC-SHA256</td><td>any</td><td>message auth</td><td>RFC 2104; combine with E-then-M</td></tr><tr><td>AEAD</td><td>AES-128-GCM</td><td>16B + 12B IV</td><td>bulk + auth</td><td>TLS 1.3 / IPsec mainline</td></tr><tr><td>AEAD</td><td>ChaCha20-Poly1305</td><td>32B + 12B</td><td>bulk + auth</td><td>mobile/IoT preferred</td></tr><tr><td>Hash</td><td>SHA-256</td><td>—</td><td>integrity, KDF, MAC</td><td>Merkle-Damgård length-extension caveat</td></tr><tr><td>Hash</td><td>SHA-3-256</td><td>—</td><td>future-proof</td><td>sponge construction</td></tr><tr><td>Hash</td><td>BLAKE3</td><td>—</td><td>parallel high-throughput</td><td>10 GB/s with AVX2</td></tr><tr><td>Password hash</td><td>Argon2id</td><td>—</td><td>password storage</td><td>PHC winner 2015; memory-hard</td></tr><tr><td>KDF</td><td>HKDF</td><td>—</td><td>derive multiple keys from master</td><td>RFC 5869</td></tr><tr><td>Public key enc</td><td>RSA-3072-OAEP</td><td>3072 b</td><td>legacy / enveloped</td><td>deprecated for new systems; use KEM</td></tr><tr><td>Public KEM</td><td>ML-KEM-768 / Kyber</td><td>~1184 B</td><td>post-quantum key exchange</td><td>FIPS 203 / RFC 9591</td></tr><tr><td>Public signature</td><td>RSA-PSS-3072</td><td>3072 b</td><td>cert signing</td><td>RFC 8017; works for TLS1.3</td></tr><tr><td>Public signature</td><td>ECDSA P-256</td><td>32B</td><td>TLS cert signing</td><td>use RFC 6979 deterministic nonce</td></tr><tr><td>Public signature</td><td>Ed25519</td><td>32B</td><td>modern signing</td><td>RFC 8032</td></tr><tr><td>Public PQ sig</td><td>ML-DSA-65 / Dilithium</td><td>~2KB</td><td>post-quantum signing</td><td>FIPS 204</td></tr><tr><td>Hash-based sig</td><td>SLH-DSA-SHA2-128f</td><td>7KB</td><td>stateless PQ hash-based</td><td>FIPS 205</td></tr><tr><td>Key exchange</td><td>X25519</td><td>32B</td><td>ephemeral ECDH</td><td>RFC 7748; constant-time</td></tr><tr><td>Key exchange</td><td>X448</td><td>56B</td><td>high-security ECDH</td><td>RFC 7748</td></tr><tr><td>KEM/sig combos</td><td>hybrid Kyber-X25519</td><td>—</td><td>TLS PQ preview</td><td>Cloudflare / Apple</td></tr><tr><td>ZK: Groth16</td><td>pairing curve BLS12</td><td>per-circuit setup</td><td>Zcash legacy</td><td>192B proof</td></tr><tr><td>ZK: PLONK</td><td>universal updatable</td><td>400B proof</td><td>zkSync Era/Scroll</td><td>O(N log N) prover</td></tr><tr><td>ZK: STARK</td><td>hash-based, transparent</td><td>~50-200KB</td><td>StarkNet post-quantum</td><td>O(log² N) verify</td></tr><tr><td>ZK: Bulletproof</td><td>curve no setup</td><td>O(log n)</td><td>Monero range proof</td><td>linear verify</td></tr></tbody></table><h2 id="a-2-—-browser-os-trust-store-matrix" tabindex="-1">A.2 — Browser / OS trust store matrix <a class="header-anchor" href="#a-2-—-browser-os-trust-store-matrix" aria-label="Permalink to &quot;A.2 — Browser / OS trust store matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>CA Program</th><th>Update Cycle</th><th>Min RSA</th><th>Min EC</th><th>SHA-1</th><th>SHA-256</th><th>Notable</th></tr></thead><tbody><tr><td>Apple root program</td><td>Yearly</td><td>2048</td><td>256</td><td>rejected</td><td>OK</td><td>private group</td></tr><tr><td>Microsoft root</td><td>Quarterly</td><td>2048</td><td>256</td><td>rejected</td><td>OK</td><td>Windows Update push</td></tr><tr><td>Mozilla / NSS</td><td>Weekly</td><td>2048</td><td>256</td><td>rejected</td><td>OK</td><td>open source program</td></tr><tr><td>Google Chrome</td><td>uses NSS</td><td>—</td><td>—</td><td>rejected</td><td>OK</td><td>CT enforcement 2018+</td></tr></tbody></table><h2 id="a-3-—-security-level-lookup-table" tabindex="-1">A.3 — Security level lookup table <a class="header-anchor" href="#a-3-—-security-level-lookup-table" aria-label="Permalink to &quot;A.3 — Security level lookup table&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Security level</th><th>Symmetric</th><th>RSA modulus</th><th>ECC modulus</th><th>SHA output</th><th>Notes</th></tr></thead><tbody><tr><td>80</td><td>80 bit</td><td>1024</td><td>160</td><td>160</td><td>retired</td></tr><tr><td>112</td><td>112</td><td>2048</td><td>224</td><td>224</td><td>RSA-2048 minimum</td></tr><tr><td>128</td><td>128</td><td>3072</td><td>256</td><td>256</td><td>TLS modern baseline</td></tr><tr><td>192</td><td>192</td><td>7680</td><td>384</td><td>384</td><td>high-sensitivity</td></tr><tr><td>256</td><td>256</td><td>15360</td><td>521</td><td>512</td><td>NSA Suite B / Type 1</td></tr></tbody></table><p>注: AES / SHA-256 在 quantum Grover 之下仍 128 等 trillion quadratic 安全, 但 RSA / ECC 在 Shor 之下 hard broken ⇒ migration to ML-KEM/ML-DSA.</p><h2 id="a-4-—-online-resources-tooling" tabindex="-1">A.4 — Online resources / tooling <a class="header-anchor" href="#a-4-—-online-resources-tooling" aria-label="Permalink to &quot;A.4 — Online resources / tooling&quot;">​</a></h2><ul><li><strong>OpenSSL</strong> command-line + library; cert generation, TLS 模拟, signature tests.</li><li><strong>Libsodium</strong> cross-language crypto 简洁 API wrapper.</li><li><strong>ring</strong> (Rust), maintained, fast OpenSSL alternative for TLS.</li><li><strong>BoringSSL</strong> Google fork, internal improvements, used by Chromium.</li><li><strong>Wireshark</strong> + <code>SSLKEYLOGFILE</code> env → decrypt own TLS sessions (debug only).</li><li><strong>Certbot</strong> / <strong>lego</strong> ACME clients for Let&#39;s Encrypt automation.</li><li><code>ssh-keygen -t ed25519</code> for modern SSH keys.</li><li><strong>age</strong> encryption tool by Filippo Valsorda — modern file encryption, X25519, AEAD.</li><li><strong>minisign</strong> for file signing (Ed25519).</li><li><strong>Snarkjs</strong> 编译零知识 proof 验证 in CLI.</li></ul><h2 id="a-5-—-common-pitfall-reminder-one-pager" tabindex="-1">A.5 — Common pitfall reminder one-pager <a class="header-anchor" href="#a-5-—-common-pitfall-reminder-one-pager" aria-label="Permalink to &quot;A.5 — Common pitfall reminder one-pager&quot;">​</a></h2><ul><li>✗ Random nonce RNG without CSPRNG → breakable keystream with predictable IV in CTR.</li><li>✗ ECDSA nonce <code>random()</code> → reuse → private key recoverable from 2 signatures.</li><li>✗ MAC-then-Encrypt → padding oracle.</li><li>✗ ECB for multi-block messages → visually leaks pattern.</li><li>✗ Passwords hashed with plain SHA-256 → rainbow-table compromise.</li><li>✗ Raw RSA <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msup><mi>m</mi><mi>e</mi></msup></mrow><annotation encoding="application/x-tex">m^e</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6644em;"></span><span class="mord"><span class="mord mathnormal">m</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6644em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="katex-sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">e</span></span></span></span></span></span></span></span></span></span></span> for small message → low-exponent attack recoverable.</li><li>✗ Same long-term signing key for multiple platforms → cross-protocol attack.</li><li>✗ ECDSA curve point input not validated → invalid-curve attack sends small subgroup point whose DLP trivial.</li><li>✓ Use libsodium / ring / OpenSSL.</li><li>✓ Rotate secrets, audit logs, monitor alerts.</li><li>✓ Constant-time comparison of secrets.</li><li>✓ AEAD encryption in 95%+ cases.</li><li>✓ Ed25519 for new signatures unless hardware constrained.</li><li>✓ X25519 / Kyber768 hybrid for new systems post-2024.</li></ul><h2 id="a-6-—-open-source-implementation-references" tabindex="-1">A.6 — Open-source implementation references <a class="header-anchor" href="#a-6-—-open-source-implementation-references" aria-label="Permalink to &quot;A.6 — Open-source implementation references&quot;">​</a></h2><ul><li>RFC 8446 TLS 1.3</li><li>RFC 7748 X25519 / X448</li><li>RFC 8032 Ed25519</li><li>RFC 7539 ChaCha20-Poly1305 AEAD</li><li>RFC 5869 HKDF</li><li>RFC 6962 Certificate Transparency</li><li>RFC 6960 OCSP</li><li>RFC 5297 AES-SIV</li><li>RFC 9591 Kyber-derived ML-KEM id encode (post-quantum)</li><li>FIPS 203 ML-KEM, 204 ML-DSA, 205 SLH-DSA standards (Aug 2024 finalized).</li></ul><h2 id="a-7-—-与项目其他章节交叉" tabindex="-1">A.7 — 与项目其他章节交叉 <a class="header-anchor" href="#a-7-—-与项目其他章节交叉" aria-label="Permalink to &quot;A.7 — 与项目其他章节交叉&quot;">​</a></h2><ul><li><strong>asymmetric.md</strong>: RSA math with CRT, ECC curve selection.</li><li><strong>tls13.md</strong>: 握手 derive secret 链; cert chain verification.</li><li><strong>sidechannel.md</strong>: time / power attack 探测:</li><li><strong>theory/complexity</strong>: PRIMES ∈ P (AKS) 提 major示范; factoring 在 NP∩co-NP but not NP-hard.</li><li><strong>distributed/fault/quorum</strong>: BFT consensus multi-party signature aggregation.</li><li><strong>system-design/case/dynamo-family</strong>: cryptographic secret 分配 among distributed storage derivatives.</li><li><strong>compilers/sema/type-system</strong>: secure &quot;opaque type&quot; 专用 防止 counter-logging from secret-annotated values.</li></ul><hr><p>下一节 → <a href="./../info-theory/">信息论与编码 README</a></p>',18)])])}const u=e(i,[["render",s]]);export{p as __pageData,u as default};
